// @ts-check
import assert from 'node:assert/strict';
import test from 'node:test';
import { screenshotFrames } from './frames.mjs';

// Complete public synthetic PNG, independently fixed rather than generated by the parser.
const pixel = 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=';
const window = { windowId: 42, pid: 123, bundleId: 'java.exe', title: 'Starsector',
    bounds: { x: 10, y: 20, width: 1, height: 1 }, isFocused: true };
const input = { target_window_id: 42, quality: 0, width: 1 };

function transcript() {
    return { info: { id: 'ses_typed' }, messages: [{ type: 'assistant', content: [
        { type: 'tool', id: 'window-1', name: 'computer_use_get_window', state: {
            status: 'completed', input: { window_id: 42 },
            content: [{ type: 'text', text: JSON.stringify(window) }],
        } },
        { type: 'tool', id: 'capture-1', name: 'computer_use_screenshot', state: {
            status: 'completed', input, content: [{ type: 'image', mimeType: 'image/png', data: pixel }],
        }, time: { created: 1, ran: 2, completed: 3 } },
    ] }] };
}

test('typed native export retains original PNG and exact native call provenance', () => {
    const frames = screenshotFrames(transcript());
    assert.equal(frames.length, 1);
    assert.deepEqual(frames[0].bytes, Buffer.from(pixel, 'base64'));
    assert.deepEqual(frames[0].metadata, {
        sessionID: 'ses_typed', callID: 'capture-1', tool: 'computer_use_screenshot',
        input, time: { created: 1, ran: 2, completed: 3 }, window,
        dimensions: { width: 1, height: 1 }, precedingActions: [], freshness: 'unknown',
    });
});

test('typed inline file and metadata content preserve the same original bytes', () => {
    for (const metadata of [false, true]) {
        const session = transcript();
        const state = /** @type {any} */ (session.messages[0].content[1].state);
        const content = [{ type: 'file', mime: 'image/png', uri: 'data:image/png;base64,' + pixel }];
        if (metadata) { delete state.content; state.metadata = { content }; }
        else state.content = content;
        assert.deepEqual(screenshotFrames(session)[0].bytes, Buffer.from(pixel, 'base64'));
    }
});

test('typed capture refuses missing or conflicting native provenance and ambiguous carriers', () => {
    /** @type {Array<(part: any) => void>} */
    const mutations = [
        part => { delete part.id; },
        part => { part.callID = 'another-call'; },
        part => { part.tool = 'computer_use_left_click'; },
        part => { part.state.input = { ...input, target_window_id: 77 }; },
        part => { part.state.attachments = [{ mime: 'image/png', url: 'data:image/png;base64,' + pixel }]; },
        part => { part.state.metadata = { content: part.state.content }; },
        part => { part.state.content.push(part.state.content[0]); },
        part => { part.state.content = [{ type: 'file', mime: 'image/png', uri: 'https://example.invalid/capture.png' }]; },
    ];
    for (const mutate of mutations) {
        const session = transcript();
        mutate(session.messages[0].content[1]);
        assert.throws(() => screenshotFrames(session));
    }
});

test('typed export keeps complete PNG framing and checksums mandatory', () => {
    const original = Buffer.from(pixel, 'base64');
    const corrupt = Buffer.from(original);
    corrupt[32] ^= 1;
    for (const bytes of [original.subarray(0, 24), original.subarray(0, -1), corrupt]) {
        const session = transcript();
        const image = /** @type {any} */ (session.messages[0].content[1].state.content[0]);
        image.data = bytes.toString('base64');
        assert.throws(() => screenshotFrames(session), /Invalid original PNG/);
    }
});
